/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { CelestialSphereScreen } from "../../src/celestial-sphere/CelestialSphereScreen.js";
import {
  createCelestialSphereIcon,
  createExplorerIcon,
  createHorizonSystemIcon,
} from "../../src/common/RotatingSkyScreenIcons.js";
import { ExplorerScreen } from "../../src/explorer/ExplorerScreen.js";
import { HorizonSystemScreen } from "../../src/horizon-system/HorizonSystemScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { RotatingSkyPreferencesModel } from "../../src/preferences/RotatingSkyPreferencesModel.js";
import RotatingSkyColors from "../../src/RotatingSkyColors.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();
  const screenNames = stringManager.getScreenNames();

  // Simulation-specific preferences; initial values come from rotatingSkyQueryParameters.
  const simPreferences = new RotatingSkyPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  // Each screen seeds its own SkyModel from the shared preference defaults.
  const screens = [
    new HorizonSystemScreen({
      preferences: simPreferences,
      // The screen name Property updates automatically when the locale changes
      name: screenNames.horizonSystemStringProperty,
      tandem: Tandem.ROOT.createTandem("horizonSystemScreen"),
      backgroundColorProperty: RotatingSkyColors.backgroundColorProperty,
      homeScreenIcon: createHorizonSystemIcon(),
      navigationBarIcon: createHorizonSystemIcon(),
    }),
    new CelestialSphereScreen({
      preferences: simPreferences,
      // The screen name Property updates automatically when the locale changes
      name: screenNames.celestialSphereStringProperty,
      tandem: Tandem.ROOT.createTandem("celestialSphereScreen"),
      backgroundColorProperty: RotatingSkyColors.backgroundColorProperty,
      homeScreenIcon: createCelestialSphereIcon(),
      navigationBarIcon: createCelestialSphereIcon(),
    }),
    new ExplorerScreen({
      preferences: simPreferences,
      // The screen name Property updates automatically when the locale changes
      name: screenNames.explorerStringProperty,
      tandem: Tandem.ROOT.createTandem("explorerScreen"),
      backgroundColorProperty: RotatingSkyColors.backgroundColorProperty,
      homeScreenIcon: createExplorerIcon(),
      navigationBarIcon: createExplorerIcon(),
    }),
  ];

  return { screens, tracked: { RotatingSkyColors, stringManager, simPreferences } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
